#!/usr/bin/env node
// tools/build-unit-index.mjs — regenerates content/units/index.json.
//
// The index claimed to be generated by this file, but the file did not exist and
// the index was maintained by hand. Anything derived from unit data therefore
// drifted silently — including the article references the dashboard needs to
// turn a heat-map tile into a link to the material.
//
// Usage: node tools/build-unit-index.mjs [--check]
//   --check exits non-zero if the checked-in index differs (for CI).

import { readFileSync, writeFileSync, readdirSync } from 'node:fs';
import { join, resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const UNIT_DIR = join(ROOT, 'content', 'units');
const ZIEL = join(UNIT_DIR, 'index.json');

/** "Art. 6 Abs. 2 lit. a" → "Art. 6" — the tile is per article, not per paragraph. */
function artikelNummer(ref) {
  const m = /^Art\.?\s*(\d+[a-z]?)/i.exec(String(ref ?? '').trim());
  return m ? `Art. ${m[1]}` : null;
}

const dateien = readdirSync(UNIT_DIR).filter(f => f.endsWith('.json') && f !== 'index.json').sort();
const units = [];
for (const f of dateien) {
  const u = JSON.parse(readFileSync(join(UNIT_DIR, f), 'utf8'));
  const refs = new Set();
  for (const cl of u.legal_basis ?? []) {
    const a = artikelNummer(cl.ref);
    if (a) refs.add(a);
  }
  // Source boxes and checks cite further articles; the map should lead there too.
  for (const b of u.blocks ?? []) {
    for (const cl of b.legal_basis ?? []) {
      const a = artikelNummer(cl.ref);
      if (a) refs.add(a);
    }
    const a = artikelNummer(b.ref ?? b.article ?? '');
    if (a) refs.add(a);
  }
  units.push({
    id: u.id, phase: u.phase, title: u.title, level: u.level, competency: u.competency,
    legal_refs: [...refs].sort((x, y) =>
      parseInt(x.slice(5), 10) - parseInt(y.slice(5), 10) || x.localeCompare(y)),
  });
}

const inhalt = JSON.stringify({ generated: 'tools/build-unit-index.mjs', units }, null, 1) + '\n';

if (process.argv.includes('--check')) {
  const ist = readFileSync(ZIEL, 'utf8');
  if (ist !== inhalt) {
    console.error('content/units/index.json ist nicht aktuell — `node tools/build-unit-index.mjs` ausführen.');
    process.exit(1);
  }
  console.log(`unit-index: aktuell (${units.length} Einheiten)`);
} else {
  writeFileSync(ZIEL, inhalt);
  const ohne = units.filter(u => !u.legal_refs.length).map(u => u.id);
  console.log(`unit-index: ${units.length} Einheiten geschrieben` +
    (ohne.length ? ` · ohne Artikelbezug: ${ohne.join(', ')}` : ''));
}
